WITH exploded AS (SELECT id, customer_id, k, attr_value FROM carts LATERAL VIEW OUTER EXPLODE(attributes) e AS k, attr_value), enriched AS (SELECT a.*, p.segment, p.name, p.credit_limit FROM exploded a LEFT JOIN customers p ON a.customer_id = p.id), base AS (SELECT *, CEIL(credit_limit) credit_limit_whole, COALESCE(segment, 'UNKNOWN') resolved_segment FROM enriched WHERE segment IS NOT NULL AND name LIKE 'O%'), base_carts AS (SELECT id, customer_id, name, credit_limit, resolved_segment, INITCAP(TRIM(k)) k_title FROM base WHERE k IS DISTINCT FROM 'utm_source') SELECT id, customer_id, credit_limit FROM base_carts ORDER BY credit_limit DESC NULLS FIRST;
